function ClusterGlyph({ shape, color, size = 10 }) {
  // Small inline swatch used in the legend so the shape (not just the color)
  // maps to each cluster, matching the scatter markers below.
  const s = size;
  const half = s / 2;
  const common = { fill: color };
  switch (shape) {
    case "diamond":
      return (
        <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
          <polygon points={`${half},0 ${s},${half} ${half},${s} 0,${half}`} {...common} />
        </svg>
      );
    case "triangle":
      return (
        <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
          <polygon points={`${half},0 ${s},${s} 0,${s}`} {...common} />
        </svg>
      );
    case "square":
      return (
        <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
          <rect width={s} height={s} {...common} />
        </svg>
      );
    case "cross":
      return (
        <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
          <polygon
            points={`${s * 0.35},0 ${s * 0.65},0 ${s * 0.65},${s * 0.35} ${s},${s * 0.35} ${s},${s * 0.65} ${s * 0.65},${s * 0.65} ${s * 0.65},${s} ${s * 0.35},${s} ${s * 0.35},${s * 0.65} 0,${s * 0.65} 0,${s * 0.35} ${s * 0.35},${s * 0.35}`}
            {...common}
          />
        </svg>
      );
    case "star": {
      const pts = [];
      for (let i = 0; i < 10; i++) {
        const r = i % 2 === 0 ? half : half * 0.42;
        const angle = (Math.PI / 5) * i - Math.PI / 2;
        pts.push(`${half + r * Math.cos(angle)},${half + r * Math.sin(angle)}`);
      }
      return (
        <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
          <polygon points={pts.join(" ")} {...common} />
        </svg>
      );
    }
    default:
      return (
        <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
          <circle cx={half} cy={half} r={half} {...common} />
        </svg>
      );
  }
}
