function clusterName(c) {
  const names = {
    0: "Abstract & Grid Games",
    1: "Drafting & Engine Building",
    2: "Economic Strategy",
    3: "Wargames & Campaigns",
    4: "Light Cards & Party",
    5: "Adventure & Dice",
  };
  return names[c.cluster] ?? `Cluster ${c.cluster}`;
}

function downloadGamesCSV(games) {
  const cols = ["name", "year", "category", "mechanic", "weight", "rating", "predicted_rating", "residual", "cluster", "playtime", "min_players", "max_players", "voters"];
  const escape = (v) => {
    if (v === null || v === undefined) return "";
    const s = String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const rows = games.map((g) => ({
    ...g,
    category: (g.categories || [])[0] || "",
    mechanic: (g.mechanics || [])[0] || "",
  }));
  const header = cols.join(",");
  const body = rows.map((r) => cols.map((c) => escape(r[c])).join(",")).join("\n");
  const csv = header + "\n" + body;
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "bgg_games_680.csv";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

